  1	//! Action classifier: maps `(method, host, path)` to an action class.
  2	//!
  3	//! Mapping configuration is compiled once. Requests are accepted only when
  4	//! their method, authority, and path have an unambiguous ASCII interpretation.
  5	
  6	mod config;
  7	mod matcher;
  8	mod normalize;
  9	
 10	use std::fmt;
 11	
 12	use config::parse;
 13	use matcher::{CompileError, CompiledRule, ConflictCheckError, find_conflict};
 14	
 15	/// Action classes a rule may name. A rule naming anything else is invalid.
 16	pub const ACTION_CLASSES: &[&str] = &[
 17	    "payment.read",
 18	    "payment.create",
 19	    "payment.refund",
 20	    "repo.read",
 21	    "repo.write",
 22	    "communication.external.send",
 23	    "llm.inference",
 24	];
 25	
 26	/// Why a set of mapping files was rejected. Set and rule indexes are 0-based
 27	/// positions in the `sets` slice and the set's `rules` array.
 28	#[derive(Debug, thiserror::Error)]
 29	pub enum LoadError {
 30	    /// One mapping set is invalid on its own. `name` is absent when the set
 31	    /// could not be parsed far enough to read it.
 32	    #[error("mapping set {set}{}: {error}", display_name(.name))]
 33	    InvalidSet {
 34	        set: usize,
 35	        name: Option<String>,
 36	        #[source]
 37	        error: SetError,
 38	    },
 39	    /// Two rules, possibly from different sets, can match the same request
 40	    /// with equal specificity but name different action classes.
 41	    #[error("{first} and {second} overlap with equal specificity but different action classes")]
 42	    ConflictingRules {
 43	        first: RuleLocation,
 44	        second: RuleLocation,
 45	    },
 46	    /// Two wildcard patterns require more overlap-analysis state than the
 47	    /// loader safely permits. Rejecting prevents configuration-driven memory
 48	    /// exhaustion without silently accepting an unresolved ambiguity.
 49	    #[error("{first} and {second} require excessive conflict analysis")]
 50	    ConflictAnalysisTooComplex {
 51	        first: RuleLocation,
 52	        second: RuleLocation,
 53	    },
 54	}
 55	
 56	/// The reason a single mapping set is invalid.
 57	#[derive(Debug, thiserror::Error)]
 58	pub enum SetError {
 59	    #[error("invalid TOML: {0}")]
 60	    Toml(#[from] toml::de::Error),
 61	    #[error("unsupported format version {0}; expected 1")]
 62	    UnsupportedFormatVersion(u32),
 63	    #[error("{0} must not be empty or malformed")]
 64	    InvalidField(&'static str),
 65	    #[error("rule {rule} has an invalid {field}")]
 66	    InvalidRule { rule: usize, field: &'static str },
 67	    #[error("rule {rule} names unsupported action class {action_class:?}")]
 68	    UnknownActionClass { rule: usize, action_class: String },
 69	}
 70	
 71	/// Where a rule came from, for conflict diagnostics.
 72	#[derive(Debug, Clone, PartialEq, Eq)]
 73	pub struct RuleLocation {
 74	    pub set: usize,
 75	    pub name: String,
 76	    pub rule: usize,
 77	}
 78	
 79	impl fmt::Display for RuleLocation {
 80	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 81	        write!(
 82	            f,
 83	            "mapping set {} {:?} rule {}",
 84	            self.set, self.name, self.rule
 85	        )
 86	    }
 87	}
 88	
 89	fn display_name(name: &Option<String>) -> String {
 90	    name.as_ref()
 91	        .map(|name| format!(" {name:?}"))
 92	        .unwrap_or_default()
 93	}
 94	
 95	/// An immutable, precompiled collection of mapping rules. Its contents are
 96	/// owned strings and therefore it is `Send + Sync` without special handling.
 97	pub struct Classifier {
 98	    rules: Vec<CompiledRule>,
 99	}
100	
101	/// Parse, validate, compile, and combine mapping sets. Configuration conflicts
102	/// are rejected here, so mapping-file ordering never affects classification.
103	pub async fn load(sets: &[&str]) -> Result<Classifier, LoadError> {
104	    let mut rules = Vec::new();
105	    let mut locations = Vec::new();
106	    for (set_index, input) in sets.iter().enumerate() {
107	        let set = parse(input).map_err(|(name, error)| LoadError::InvalidSet {
108	            set: set_index,
109	            name,
110	            error,
111	        })?;
112	        for (rule_index, rule) in set.rules.into_iter().enumerate() {
113	            // Validation already ran these checks, so this mapping only
114	            // guards against the two modules drifting apart.
115	            let compiled = CompiledRule::new(
116	                rule.method.as_deref(),
117	                &set.host,
118	                rule.subdomain.as_deref(),
119	                rule.path.as_deref(),
120	                rule.action_class,
121	            )
122	            .map_err(|error| LoadError::InvalidSet {
123	                set: set_index,
124	                name: Some(set.name.clone()),
125	                error: SetError::InvalidRule {
126	                    rule: rule_index,
127	                    field: match error {
128	                        CompileError::Host => "subdomain",
129	                        CompileError::Method => "method",
130	                        CompileError::Path => "path",
131	                    },
132	                },
133	            })?;
134	            rules.push(compiled);
135	            locations.push(RuleLocation {
136	                set: set_index,
137	                name: set.name.clone(),
138	                rule: rule_index,
139	            });
140	        }
141	    }
142	    match find_conflict(&rules) {
143	        Ok(Some((first, second))) => {
144	            return Err(LoadError::ConflictingRules {
145	                first: locations[first].clone(),
146	                second: locations[second].clone(),
147	            });
148	        }
149	        Ok(None) => {}
150	        Err(ConflictCheckError::TooComplex { first, second }) => {
151	            return Err(LoadError::ConflictAnalysisTooComplex {
152	                first: locations[first].clone(),
153	                second: locations[second].clone(),
154	            });
155	        }
156	    }
157	    Ok(Classifier { rules })
158	}
159	
160	impl Classifier {
161	    /// Classifies a request. Malformed input is deliberately unclassified
162	    /// rather than coerced into a potentially broader rule.
163	    pub async fn classify(&self, method: &str, host: &str, path: &str) -> Option<&str> {
164	        let method = normalize::method(method)?;
165	        let host = normalize::host(host)?;
166	        let path = normalize::request_path(path)?;
167	        let class = self.best_match(&method, &host, &path);
168	
169	        // Many servers route `/x/` and `/x` to the same handler. If the two
170	        // spellings classify differently we cannot know which action runs, so
171	        // the request is left unclassified (and therefore denied).
172	        let alternate_path = match path.strip_suffix('/').filter(|rest| !rest.is_empty()) {
173	            Some(stripped) => stripped.to_owned(),
174	            None if path != "/" => format!("{path}/"),
175	            None => return class,
176	        };
177	        if let (Some(class), Some(alternative)) =
178	            (class, self.best_match(&method, &host, &alternate_path))
179	            && alternative != class
180	        {
181	            return None;
182	        }
183	        class
184	    }
185	
186	    fn best_match(&self, method: &str, host: &str, path: &str) -> Option<&str> {
187	        self.rules
188	            .iter()
189	            .filter(|rule| rule.matches(method, host, path))
190	            .max_by(|left, right| left.compare_specificity(right))
191	            .map(|rule| rule.action_class.as_str())
192	    }
193	}
  1	//! Canonicalization for the three request components accepted by the classifier.
  2	//!
  3	//! This module deliberately accepts only the unambiguous ASCII subset of HTTP
  4	//! authority and path syntax. In particular, IP literals, userinfo, encoded
  5	//! separators, malformed percent escapes, and non-ASCII text are rejected.
  6	
  7	/// Returns a lowercase DNS hostname without one optional trailing dot or port.
  8	pub(crate) fn host(input: &str) -> Option<String> {
  9	    if input.is_empty() || !input.is_ascii() || input.contains('@') {
 10	        return None;
 11	    }
 12	
 13	    let (name, port) = match input.rsplit_once(':') {
 14	        Some((name, port)) => (name, Some(port)),
 15	        None => (input, None),
 16	    };
 17	    // Parsing also rejects values outside the TCP/UDP port range.
 18	    if let Some(port) = port
 19	        && (!port.bytes().all(|byte| byte.is_ascii_digit()) || port.parse::<u16>().is_err())
 20	    {
 21	        return None;
 22	    }
 23	
 24	    let name = name.strip_suffix('.').unwrap_or(name);
 25	    if !is_dns_name(name) || name.parse::<std::net::Ipv4Addr>().is_ok() {
 26	        return None;
 27	    }
 28	    Some(name.to_ascii_lowercase())
 29	}
 30	
 31	/// Validates an HTTP token and folds it to uppercase. HTTP methods are
 32	/// case-sensitive on the wire, but clients and servers commonly normalize
 33	/// them; folding prevents a lowercase spelling from bypassing a stricter
 34	/// uppercase rule and falling through to a broader rule.
 35	pub(crate) fn method(input: &str) -> Option<String> {
 36	    (!input.is_empty() && input.bytes().all(is_http_token)).then(|| input.to_ascii_uppercase())
 37	}
 38	
 39	/// Normalizes a request path. Empty input represents the origin-form `/`.
 40	pub(crate) fn request_path(input: &str) -> Option<String> {
 41	    let end = input.find(['?', '#']).unwrap_or(input.len());
 42	    let path = &input[..end];
 43	    if path.is_empty() {
 44	        return Some("/".into());
 45	    }
 46	    normalize_path(path, false)
 47	}
 48	
 49	/// Normalizes a configuration path pattern while retaining literal `*`
 50	/// wildcards. Query strings and fragments never reach the matcher, so a
 51	/// pattern containing one is a configuration mistake.
 52	pub(crate) fn pattern_path(input: &str) -> Option<String> {
 53	    if input.contains(['?', '#']) {
 54	        return None;
 55	    }
 56	    normalize_path(input, true)
 57	}
 58	
 59	/// Canonical form shared by requests and patterns: unreserved percent escapes
 60	/// decoded, other escapes upper-cased, and dot segments removed. Empty path
 61	/// segments, backslashes, and encoded separators are rejected because servers
 62	/// disagree on what they mean.
 63	fn normalize_path(input: &str, pattern: bool) -> Option<String> {
 64	    if !input.starts_with('/') {
 65	        return None;
 66	    }
 67	    let decoded = decode_unreserved(input)?;
 68	    if decoded.contains("//") {
 69	        return None;
 70	    }
 71	
 72	    // A dot segment next to a wildcard cannot be canonicalized soundly: the
 73	    // wildcard can span an unknown number of path segments. Reject rather than
 74	    // assigning it a meaning that a URL client or server may not share.
 75	    if pattern
 76	        && decoded.contains('*')
 77	        && decoded
 78	            .split('/')
 79	            .any(|segment| segment == "." || segment == "..")
 80	    {
 81	        return None;
 82	    }
 83	    Some(remove_dot_segments(&decoded))
 84	}
 85	
 86	/// RFC 3986 section 6.2.2 normalization: `%72` and `r` are the same path, so
 87	/// decode escaped unreserved bytes and upper-case the rest. Decoding happens
 88	/// once; `%25` stays `%25`.
 89	fn decode_unreserved(input: &str) -> Option<String> {
 90	    const HEX: &[u8; 16] = b"0123456789ABCDEF";
 91	    let bytes = input.as_bytes();
 92	    let mut output = String::with_capacity(input.len());
 93	    let mut index = 0;
 94	    while let Some(&byte) = bytes.get(index) {
 95	        if byte == b'%' {
 96	            let hi = hex(*bytes.get(index + 1)?)?;
 97	            let lo = hex(*bytes.get(index + 2)?)?;
 98	            let value = (hi << 4) | lo;
 99	            if matches!(value, b'/' | b'\\') {
100	                return None;
101	            }
102	            if value.is_ascii_alphanumeric() || matches!(value, b'-' | b'.' | b'_' | b'~') {
103	                output.push(char::from(value));
104	            } else {
105	                output.push('%');
106	                output.push(char::from(HEX[usize::from(hi)]));
107	                output.push(char::from(HEX[usize::from(lo)]));
108	            }
109	            index += 3;
110	        } else {
111	            if !byte.is_ascii_graphic() || byte == b'\\' {
112	                return None;
113	            }
114	            output.push(char::from(byte));
115	            index += 1;
116	        }
117	    }
118	    Some(output)
119	}
120	
121	fn hex(byte: u8) -> Option<u8> {
122	    match byte {
123	        b'0'..=b'9' => Some(byte - b'0'),
124	        b'a'..=b'f' => Some(byte - b'a' + 10),
125	        b'A'..=b'F' => Some(byte - b'A' + 10),
126	        _ => None,
127	    }
128	}
129	
130	/// RFC 3986 dot-segment removal for an absolute path without empty segments.
131	/// A stack keeps this linear in the path length.
132	fn remove_dot_segments(input: &str) -> String {
133	    let mut segments = Vec::new();
134	    // A path ending in `.` or `..` names a directory, as `/a/b/..` -> `/a/`.
135	    let mut trailing_slash = false;
136	    for segment in input.split('/').skip(1) {
137	        match segment {
138	            "." => trailing_slash = true,
139	            ".." => {
140	                segments.pop();
141	                trailing_slash = true;
142	            }
143	            _ => {
144	                segments.push(segment);
145	                trailing_slash = false;
146	            }
147	        }
148	    }
149	    let mut output = format!("/{}", segments.join("/"));
150	    if trailing_slash && !output.ends_with('/') {
151	        output.push('/');
152	    }
153	    output
154	}
155	
156	fn is_dns_name(value: &str) -> bool {
157	    !value.is_empty()
158	        && value.len() <= 253
159	        && value.split('.').all(|label| {
160	            !label.is_empty()
161	                && label.len() <= 63
162	                && !label.starts_with('-')
163	                && !label.ends_with('-')
164	                && label
165	                    .bytes()
166	                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
167	        })
168	}
169	
170	fn is_http_token(byte: u8) -> bool {
171	    byte.is_ascii_alphanumeric()
172	        || matches!(
173	            byte,
174	            b'!' | b'#'
175	                | b'$'
176	                | b'%'
177	                | b'&'
178	                | b'\''
179	                | b'*'
180	                | b'+'
181	                | b'-'
182	                | b'.'
183	                | b'^'
184	                | b'_'
185	                | b'`'
186	                | b'|'
187	                | b'~'
188	        )
189	}
