195	    #[test]
196	    fn normalizes_hosts_and_rejects_ambiguous_authorities() {
197	        assert_eq!(host("API.Acme.COM.:443"), Some("api.acme.com".into()));
198	        for value in [
199	            "",
200	            "acme.com:",
201	            "acme.com:99999",
202	            "u@acme.com",
203	            "192.0.2.1",
204	            "[::1]",
205	            "acme..com",
206	            "é.com",
207	            "acme.com..",
208	        ] {
209	            assert_eq!(host(value), None, "{value}");
210	        }
211	    }
212	
213	    #[test]
214	    fn methods_are_tokens_folded_to_upper_case() {
215	        assert_eq!(method("GET"), Some("GET".into()));
216	        assert_eq!(method("delete"), Some("DELETE".into()));
217	        assert_eq!(method("Patch"), Some("PATCH".into()));
218	        for value in ["", "GET ", "GET\n", "é"] {
219	            assert_eq!(method(value), None, "{value:?}");
220	        }
221	    }
222	
223	    #[test]
224	    fn paths_strip_query_and_normalize_dot_segments() {
225	        assert_eq!(request_path(""), Some("/".into()));
226	        assert_eq!(request_path("/v1/../admin?q=1#x"), Some("/admin".into()));
227	        assert_eq!(request_path("/v1/%2e%2e/admin"), Some("/admin".into()));
228	        assert_eq!(request_path("/a/b/.."), Some("/a/".into()));
229	        assert_eq!(request_path("/a/./b/."), Some("/a/b/".into()));
230	        assert_eq!(request_path("/../../x"), Some("/x".into()));
231	        assert_eq!(request_path("/v1/payments/"), Some("/v1/payments/".into()));
232	        for value in [
233	            "relative", "/x%ZZ", "/x%2f", "/x%5C", "/x\\y", "/é", "/a b", "/a\0", "/v1//x", "//",
234	        ] {
235	            assert_eq!(request_path(value), None, "{value:?}");
236	        }
237	    }
238	
239	    #[test]
240	    fn paths_decode_unreserved_escapes_only() {
241	        assert_eq!(request_path("/v1/%72efunds"), Some("/v1/refunds".into()));
242	        assert_eq!(request_path("/%7Euser/%5f"), Some("/~user/_".into()));
243	        assert_eq!(request_path("/a%3a%2A"), Some("/a%3A%2A".into()));
244	        // No double decoding: `%252e` is a literal `%2e`, not a dot segment.
245	        assert_eq!(
246	            request_path("/a/%252e%252e/b"),
247	            Some("/a/%252e%252e/b".into())
248	        );
249	    }
