251	    #[test]
252	    fn patterns_retain_wildcards_but_reject_ambiguous_dot_patterns() {
253	        assert_eq!(
254	            pattern_path("/v1/*/refunds/**"),
255	            Some("/v1/*/refunds/**".into())
256	        );
257	        assert_eq!(
258	            pattern_path("/v1/%72efunds/*"),
259	            Some("/v1/refunds/*".into())
260	        );
261	        assert_eq!(pattern_path("/v1/*/../admin"), None);
262	        assert_eq!(pattern_path("/v1/*?debug=true"), None);
263	        assert_eq!(pattern_path("/v1//x"), None);
264	    }
