266	    #[test]
267	    fn long_and_arbitrary_utf8_request_inputs_never_panic() {
268	        assert!(request_path(&format!("/{}", "a".repeat(32 * 1024))).is_some());
269	        for value in ["\0", "\u{10ffff}", "/\u{10ffff}", "/%"] {
270	            assert_eq!(request_path(value), None, "{value:?}");
271	        }
272	    }
273	}

  1	//! Parsing and validation for mapping-set TOML documents.
  2	
  3	use serde::Deserialize;
  4	
  5	use crate::{ACTION_CLASSES, SetError, normalize};
  6	
  7	#[derive(Debug, Deserialize)]
  8	#[serde(deny_unknown_fields)]
  9	pub(crate) struct MappingSet {
 10	    pub(crate) format_version: u32,
 11	    pub(crate) name: String,
 12	    pub(crate) description: Option<String>,
 13	    pub(crate) host: String,
 14	    pub(crate) rules: Vec<Rule>,
 15	}
 16	
 17	#[derive(Debug, Deserialize)]
 18	#[serde(deny_unknown_fields)]
 19	pub(crate) struct Rule {
 20	    pub(crate) method: Option<String>,
 21	    pub(crate) subdomain: Option<String>,
 22	    pub(crate) path: Option<String>,
 23	    pub(crate) action_class: String,
 24	}
 25	
 26	/// Converts one TOML document to a checked mapping set. Errors carry the
 27	/// set's declared name when the document parsed far enough to have one.
 28	pub(crate) fn parse(input: &str) -> Result<MappingSet, (Option<String>, SetError)> {
 29	    let set: MappingSet = toml::from_str(input).map_err(|error| (None, SetError::Toml(error)))?;
 30	    match validate(&set) {
 31	        Ok(()) => Ok(set),
 32	        Err(error) => Err((Some(set.name), error)),
 33	    }
 34	}
 35	
 36	fn validate(set: &MappingSet) -> Result<(), SetError> {
 37	    if set.format_version != 1 {
 38	        return Err(SetError::UnsupportedFormatVersion(set.format_version));
 39	    }
 40	    required_text("name", &set.name)?;
 41	    if set
 42	        .description
 43	        .as_deref()
 44	        .is_some_and(|description| description.chars().any(char::is_control))
 45	    {
 46	        return Err(SetError::InvalidField("description"));
 47	    }
 48	    validate_host(&set.host)?;
 49	    if set.rules.is_empty() {
 50	        return Err(SetError::InvalidField("rules"));
 51	    }
 52	
 53	    for (index, rule) in set.rules.iter().enumerate() {
 54	        if !ACTION_CLASSES.contains(&rule.action_class.as_str()) {
 55	            return Err(SetError::UnknownActionClass {
 56	                rule: index,
 57	                action_class: rule.action_class.clone(),
 58	            });
 59	        }
 60	        if let Some(method) = &rule.method
 61	            && normalize::method(method).is_none()
 62	        {
 63	            return Err(SetError::InvalidRule {
 64	                rule: index,
 65	                field: "method",
 66	            });
 67	        }
 68	        if let Some(subdomain) = &rule.subdomain
 69	            && subdomain != "*"
 70	            && (!is_dns_name(subdomain) || normalize::host(subdomain).is_none())
 71	        {
 72	            return Err(SetError::InvalidRule {
 73	                rule: index,
 74	                field: "subdomain",
 75	            });
 76	        }
 77	        if let Some(path) = &rule.path
 78	            && normalize::pattern_path(path).is_none()
 79	        {
 80	            return Err(SetError::InvalidRule {
 81	                rule: index,
 82	                field: "path",
 83	            });
 84	        }
 85	    }
 86	    Ok(())
 87	}
 88	
 89	fn required_text(field: &'static str, value: &str) -> Result<(), SetError> {
 90	    if value.trim().is_empty() || value.chars().any(char::is_control) {
 91	        Err(SetError::InvalidField(field))
 92	    } else {
 93	        Ok(())
 94	    }
 95	}
 96	
 97	fn validate_host(host: &str) -> Result<(), SetError> {
 98	    // Mapping hosts name an origin, not an HTTP authority. Ports and trailing
 99	    // dots are accepted for request authorities but create duplicate mapping
100	    // identities, so reject them here.
101	    if !host.contains(':')
102	        && !host.ends_with('.')
103	        && normalize::host(host).is_some()
104	        && is_dns_name(host)
105	    {
106	        Ok(())
107	    } else {
108	        Err(SetError::InvalidField("host"))
109	    }
110	}
111	
112	fn is_dns_name(value: &str) -> bool {
113	    !value.is_empty() && value.len() <= 253 && value.split('.').all(is_dns_label)
114	}
115	
116	fn is_dns_label(value: &str) -> bool {
117	    !value.is_empty()
118	        && value.len() <= 63
119	        && !value.starts_with('-')
120	        && !value.ends_with('-')
121	        && value
122	            .bytes()
123	            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
124	}
125	
126	#[cfg(test)]
127	mod tests {
128	    use super::parse;
129	
130	    const VALID: &str = r#"
131	format_version = 1
132	name = "Acme"
133	description = "Acme API"
134	host = "acme.com"
135	
136	[[rules]]
137	action_class = "payment.read"
138	"#;
139	
140	    #[test]
141	    fn parses_a_valid_mapping_set() {
142	        let set = parse(VALID).unwrap();
143	        assert_eq!(set.host, "acme.com");
144	        assert_eq!(set.rules.len(), 1);
145	    }
146	
147	    #[test]
148	    fn rejects_missing_required_top_level_fields() {
149	        for field in [
150	            "format_version = 1\n",
151	            "name = \"Acme\"\n",
152	            "host = \"acme.com\"\n",
153	        ] {
154	            let input = VALID.replace(field, "");
