  1	//! Compiled-rule matching, lexicographic specificity, and load-time conflicts.
  2	
  3	use std::cmp::Ordering;
  4	
  5	use crate::normalize;
  6	
  7	#[derive(Debug, Clone, PartialEq, Eq)]
  8	pub(crate) enum HostPattern {
  9	    Bare(String),
 10	    Exact(String),
 11	    AnySubdomain(String),
 12	}
 13	
 14	#[derive(Debug, Clone)]
 15	pub(crate) struct CompiledRule {
 16	    pub(crate) method: Option<String>,
 17	    pub(crate) host: HostPattern,
 18	    pub(crate) path: Option<String>,
 19	    pub(crate) action_class: String,
 20	    specificity: Specificity,
 21	}
 22	
 23	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 24	struct Specificity {
 25	    host: u8,
 26	    path_kind: u8,
 27	    literal_count: usize,
 28	    inverted_wildcard_count: usize,
 29	    literal_prefix: usize,
 30	    method: u8,
 31	}
 32	
 33	impl Ord for Specificity {
 34	    fn cmp(&self, other: &Self) -> Ordering {
 35	        (
 36	            self.host,
 37	            self.path_kind,
 38	            self.literal_count,
 39	            self.inverted_wildcard_count,
 40	            self.literal_prefix,
 41	            self.method,
 42	        )
 43	            .cmp(&(
 44	                other.host,
 45	                other.path_kind,
 46	                other.literal_count,
 47	                other.inverted_wildcard_count,
 48	                other.literal_prefix,
 49	                other.method,
 50	            ))
 51	    }
 52	}
 53	
 54	impl PartialOrd for Specificity {
 55	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
 56	        Some(self.cmp(other))
 57	    }
 58	}
 59	
 60	#[derive(Debug)]
 61	pub(crate) enum CompileError {
 62	    Host,
 63	    Method,
 64	    Path,
 65	}
 66	
 67	#[derive(Debug)]
 68	pub(crate) enum ConflictCheckError {
 69	    TooComplex { first: usize, second: usize },
 70	}
 71	
 72	impl CompiledRule {
 73	    pub(crate) fn new(
 74	        method: Option<&str>,
 75	        base_host: &str,
 76	        subdomain: Option<&str>,
 77	        path: Option<&str>,
 78	        action_class: String,
 79	    ) -> Result<Self, CompileError> {
 80	        let base_host = normalize::host(base_host).ok_or(CompileError::Host)?;
 81	        let host = match subdomain {
 82	            None => HostPattern::Bare(base_host),
 83	            Some("*") => HostPattern::AnySubdomain(base_host),
 84	            Some(value) => {
 85	                let value = normalize::host(value).ok_or(CompileError::Host)?;
 86	                HostPattern::Exact(format!("{value}.{base_host}"))
 87	            }
 88	        };
 89	        let method = match method {
 90	            Some(value) => Some(normalize::method(value).ok_or(CompileError::Method)?),
 91	            None => None,
 92	        };
 93	        let path = match path {
 94	            Some(value) => Some(normalize::pattern_path(value).ok_or(CompileError::Path)?),
 95	            None => None,
 96	        };
 97	        let specificity = specificity(&host, method.is_some(), path.as_deref());
 98	        Ok(Self {
 99	            method,
100	            host,
101	            path,
102	            action_class,
103	            specificity,
104	        })
105	    }
106	
107	    pub(crate) fn matches(&self, method: &str, host: &str, path: &str) -> bool {
108	        self.method
109	            .as_deref()
110	            .is_none_or(|expected| expected == method)
111	            && host_matches(&self.host, host)
112	            && self
113	                .path
114	                .as_deref()
115	                .is_none_or(|pattern| glob_matches(pattern, path))
116	    }
117	
118	    pub(crate) fn compare_specificity(&self, other: &Self) -> Ordering {
119	        self.specificity.cmp(&other.specificity)
120	    }
121	}
122	
123	pub(crate) fn find_conflict(
124	    rules: &[CompiledRule],
125	) -> Result<Option<(usize, usize)>, ConflictCheckError> {
126	    let mut checked_pairs = 0;
127	    for (right_index, right) in rules.iter().enumerate() {
128	        for (left_index, left) in rules[..right_index].iter().enumerate() {
129	            checked_pairs += 1;
130	            if checked_pairs > MAX_CONFLICT_PAIR_CHECKS {
131	                return Err(ConflictCheckError::TooComplex {
132	                    first: left_index,
133	                    second: right_index,
134	                });
135	            }
136	            if left.action_class != right.action_class
137	                && left.specificity == right.specificity
138	                && methods_overlap(left.method.as_deref(), right.method.as_deref())
139	                && hosts_overlap(&left.host, &right.host)
140	            {
141	                match paths_overlap(left.path.as_deref(), right.path.as_deref()) {
142	                    Ok(true) => return Ok(Some((left_index, right_index))),
143	                    Ok(false) => {}
144	                    Err(()) => {
145	                        return Err(ConflictCheckError::TooComplex {
146	                            first: left_index,
147	                            second: right_index,
148	                        });
149	                    }
150	                }
151	            }
152	        }
153	    }
154	    Ok(None)
155	}
156	
157	fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
158	    let host = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
159	    let (path_kind, literal_count, wildcard_count, literal_prefix) = match path {
160	        None => (0, 0, 0, 0),
161	        Some(value) if !value.contains('*') => (2, value.len(), 0, value.len()),
162	        Some(value) => (
163	            1,
164	            value.bytes().filter(|byte| *byte != b'*').count(),
165	            value.bytes().filter(|byte| *byte == b'*').count(),
166	            value.find('*').unwrap_or(0),
167	        ),
168	    };
169	    Specificity {
170	        host,
171	        path_kind,
172	        literal_count,
173	        inverted_wildcard_count: usize::MAX - wildcard_count,
174	        literal_prefix,
175	        method: u8::from(has_method),
176	    }
177	}
178	
179	fn host_matches(pattern: &HostPattern, host: &str) -> bool {
180	    match pattern {
181	        HostPattern::Bare(expected) | HostPattern::Exact(expected) => expected == host,
182	        HostPattern::AnySubdomain(base) => host
183	            .strip_suffix(base)
184	            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1),
185	    }
186	}
187	
188	fn methods_overlap(left: Option<&str>, right: Option<&str>) -> bool {
189	    left.is_none() || right.is_none() || left == right
190	}
191	
192	fn hosts_overlap(left: &HostPattern, right: &HostPattern) -> bool {
193	    match (left, right) {
194	        (HostPattern::Bare(a), HostPattern::Bare(b))
195	        | (HostPattern::Bare(a), HostPattern::Exact(b))
196	        | (HostPattern::Exact(a), HostPattern::Bare(b))
197	        | (HostPattern::Exact(a), HostPattern::Exact(b)) => a == b,
198	        // These pairs cannot have equal host specificity, but retain correct
199	        // overlap semantics for callers that want them.
200	        (HostPattern::AnySubdomain(base), HostPattern::Bare(host))
201	        | (HostPattern::Bare(host), HostPattern::AnySubdomain(base))
202	        | (HostPattern::AnySubdomain(base), HostPattern::Exact(host))
203	        | (HostPattern::Exact(host), HostPattern::AnySubdomain(base)) => {
204	            host_matches(&HostPattern::AnySubdomain(base.clone()), host)
205	        }
206	        (HostPattern::AnySubdomain(a), HostPattern::AnySubdomain(b)) => {
207	            a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"))
208	        }
209	    }
210	}
211	
212	fn paths_overlap(left: Option<&str>, right: Option<&str>) -> Result<bool, ()> {
213	    match (left, right) {
214	        (None, _) | (_, None) => Ok(true),
215	        (Some(left), Some(right)) => globs_overlap(left, right),
216	    }
217	}
218	
219	pub(crate) fn glob_matches(pattern: &str, value: &str) -> bool {
220	    let pattern = pattern.as_bytes();
221	    let value = value.as_bytes();
222	    let (mut p, mut v, mut star, mut retry) = (0, 0, None, 0);
223	    while v < value.len() {
224	        while p < pattern.len() && pattern[p] == b'*' {
225	            star = Some(p);
226	            p += 1;
227	            retry = v;
228	        }
229	        if p < pattern.len() && pattern[p] == value[v] {
230	            p += 1;
231	            v += 1;
232	        } else if let Some(star_index) = star {
233	            p = star_index + 1;
234	            retry += 1;
235	            v = retry;
236	        } else {
237	            return false;
238	        }
239	    }
240	    while p < pattern.len() && pattern[p] == b'*' {
241	        p += 1;
242	    }
243	    p == pattern.len()
244	}
245	
246	/// Product traversal of two `*` glob NFAs. The sentinel represents any byte
247	/// not currently present as a literal and keeps the alphabet finite.
248	const MAX_GLOB_OVERLAP_STATES: usize = 1_000_000;
249	const MAX_CONFLICT_PAIR_CHECKS: usize = 100_000;
250	
251	fn globs_overlap(left: &str, right: &str) -> Result<bool, ()> {
252	    let (left, right) = (left.as_bytes(), right.as_bytes());
253	    let width = right.len().checked_add(1).ok_or(())?;
254	    let states = left
255	        .len()
256	        .checked_add(1)
257	        .and_then(|height| height.checked_mul(width))
258	        .filter(|states| *states <= MAX_GLOB_OVERLAP_STATES)
259	        .ok_or(())?;
260	    let mut seen = vec![false; states];
261	    let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
262	    while let Some((i, j)) = queue.pop_front() {
263	        let state = i * width + j;
264	        if seen[state] {
265	            continue;
266	        }
267	        seen[state] = true;
268	        if i == left.len() && j == right.len() {
269	            return Ok(true);
270	        }
271	        if left.get(i) == Some(&b'*') {
272	            queue.push_back((i + 1, j));
273	        }
274	        if right.get(j) == Some(&b'*') {
275	            queue.push_back((i, j + 1));
276	        }
277	        let mut alphabet = vec![0];
278	        if let Some(&byte) = left.get(i).filter(|&&byte| byte != b'*') {
279	            alphabet.push(byte);
280	        }
281	        if let Some(&byte) = right.get(j).filter(|&&byte| byte != b'*') {
282	            alphabet.push(byte);
283	        }
284	        for byte in alphabet {
285	            let next_left = transition(left, i, byte);
286	            let next_right = transition(right, j, byte);
287	            if let (Some(next_left), Some(next_right)) = (next_left, next_right) {
288	                queue.push_back((next_left, next_right));
289	            }
290	        }
291	    }
292	    Ok(false)
293	}
294	
295	fn transition(pattern: &[u8], index: usize, byte: u8) -> Option<usize> {
296	    match pattern.get(index) {
297	        Some(b'*') => Some(index),
298	        Some(&literal) if literal == byte => Some(index + 1),
299	        _ => None,
300	    }
301	}
