101	/// Parse, validate, compile, and combine mapping sets. Configuration conflicts
102	/// are rejected here, so mapping-file ordering never affects classification.
103	pub async fn load(sets: &[&str]) -> Result<Classifier, LoadError> {
104	    let mut rules = Vec::new();
105	    let mut locations = Vec::new();
106	    for (set_index, input) in sets.iter().enumerate() {
107	        let set = parse(input).map_err(|(name, error)| LoadError::InvalidSet {
108	            set: set_index,
109	            name,
110	            error,
111	        })?;
112	        for (rule_index, rule) in set.rules.into_iter().enumerate() {
113	            // Validation already ran these checks, so this mapping only
114	            // guards against the two modules drifting apart.
115	            let compiled = CompiledRule::new(
116	                rule.method.as_deref(),
117	                &set.host,
118	                rule.subdomain.as_deref(),
119	                rule.path.as_deref(),
120	                rule.action_class,
121	            )
122	            .map_err(|error| LoadError::InvalidSet {
123	                set: set_index,
124	                name: Some(set.name.clone()),
125	                error: SetError::InvalidRule {
126	                    rule: rule_index,
127	                    field: match error {
128	                        CompileError::Host => "subdomain",
129	                        CompileError::Method => "method",
130	                        CompileError::Path => "path",
131	                    },
132	                },
133	            })?;
134	            rules.push(compiled);
135	            locations.push(RuleLocation {
136	                set: set_index,
137	                name: set.name.clone(),
138	                rule: rule_index,
139	            });
140	        }
141	    }
142	    match find_conflict(&rules) {
143	        Ok(Some((first, second))) => {
144	            return Err(LoadError::ConflictingRules {
145	                first: locations[first].clone(),
146	                second: locations[second].clone(),
147	            });
148	        }
149	        Ok(None) => {}
150	        Err(ConflictCheckError::TooComplex { first, second }) => {
151	            return Err(LoadError::ConflictAnalysisTooComplex {
152	                first: locations[first].clone(),
153	                second: locations[second].clone(),
154	            });
155	        }
156	    }
157	    Ok(Classifier { rules })
158	}
