 39	/// Normalizes a request path. Empty input represents the origin-form `/`.
 40	pub(crate) fn request_path(input: &str) -> Option<String> {
 41	    let end = input.find(['?', '#']).unwrap_or(input.len());
 42	    let path = &input[..end];
 43	    if path.is_empty() {
 44	        return Some("/".into());
 45	    }
 46	    normalize_path(path, false)
 47	}
 48	
 49	/// Normalizes a configuration path pattern while retaining literal `*`
 50	/// wildcards. Query strings and fragments never reach the matcher, so a
 51	/// pattern containing one is a configuration mistake.
 52	pub(crate) fn pattern_path(input: &str) -> Option<String> {
 53	    if input.contains(['?', '#']) {
 54	        return None;
 55	    }
 56	    normalize_path(input, true)
 57	}
 58	
 59	/// Canonical form shared by requests and patterns: unreserved percent escapes
 60	/// decoded, other escapes upper-cased, and dot segments removed. Empty path
 61	/// segments, backslashes, and encoded separators are rejected because servers
 62	/// disagree on what they mean.
 63	fn normalize_path(input: &str, pattern: bool) -> Option<String> {
 64	    if !input.starts_with('/') {
 65	        return None;
 66	    }
 67	    let decoded = decode_unreserved(input)?;
 68	    if decoded.contains("//") {
 69	        return None;
 70	    }
 71	
 72	    // A dot segment next to a wildcard cannot be canonicalized soundly: the
 73	    // wildcard can span an unknown number of path segments. Reject rather than
 74	    // assigning it a meaning that a URL client or server may not share.
 75	    if pattern
 76	        && decoded.contains('*')
 77	        && decoded
 78	            .split('/')
 79	            .any(|segment| segment == "." || segment == "..")
 80	    {
 81	        return None;
 82	    }
 83	    Some(remove_dot_segments(&decoded))
 84	}
 85	
 86	/// RFC 3986 section 6.2.2 normalization: `%72` and `r` are the same path, so
 87	/// decode escaped unreserved bytes and upper-case the rest. Decoding happens
 88	/// once; `%25` stays `%25`.
 89	fn decode_unreserved(input: &str) -> Option<String> {
 90	    const HEX: &[u8; 16] = b"0123456789ABCDEF";
 91	    let bytes = input.as_bytes();
 92	    let mut output = String::with_capacity(input.len());
 93	    let mut index = 0;
 94	    while let Some(&byte) = bytes.get(index) {
 95	        if byte == b'%' {
 96	            let hi = hex(*bytes.get(index + 1)?)?;
 97	            let lo = hex(*bytes.get(index + 2)?)?;
 98	            let value = (hi << 4) | lo;
 99	            if matches!(value, b'/' | b'\\') {
100	                return None;
101	            }
102	            if value.is_ascii_alphanumeric() || matches!(value, b'-' | b'.' | b'_' | b'~') {
103	                output.push(char::from(value));
104	            } else {
105	                output.push('%');
106	                output.push(char::from(HEX[usize::from(hi)]));
107	                output.push(char::from(HEX[usize::from(lo)]));
108	            }
109	            index += 3;
110	        } else {
111	            if !byte.is_ascii_graphic() || byte == b'\\' {
112	                return None;
113	            }
114	            output.push(char::from(byte));
115	            index += 1;
116	        }
117	    }
118	    Some(output)
119	}
120	
121	fn hex(byte: u8) -> Option<u8> {
122	    match byte {
123	        b'0'..=b'9' => Some(byte - b'0'),
124	        b'a'..=b'f' => Some(byte - b'a' + 10),
125	        b'A'..=b'F' => Some(byte - b'A' + 10),
126	        _ => None,
127	    }
128	}
129	
130	/// RFC 3986 dot-segment removal for an absolute path without empty segments.
131	/// A stack keeps this linear in the path length.
132	fn remove_dot_segments(input: &str) -> String {
133	    let mut segments = Vec::new();
134	    // A path ending in `.` or `..` names a directory, as `/a/b/..` -> `/a/`.
135	    let mut trailing_slash = false;
136	    for segment in input.split('/').skip(1) {
137	        match segment {
138	            "." => trailing_slash = true,
139	            ".." => {
140	                segments.pop();
141	                trailing_slash = true;
142	            }
143	            _ => {
144	                segments.push(segment);
145	                trailing_slash = false;
146	            }
147	        }
148	    }
149	    let mut output = format!("/{}", segments.join("/"));
150	    if trailing_slash && !output.ends_with('/') {
151	        output.push('/');
152	    }
153	    output
154	}
155	
156	fn is_dns_name(value: &str) -> bool {
157	    !value.is_empty()
158	        && value.len() <= 253
159	        && value.split('.').all(|label| {
160	            !label.is_empty()
161	                && label.len() <= 63
162	                && !label.starts_with('-')
163	                && !label.ends_with('-')
164	                && label
165	                    .bytes()
166	                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
167	        })
168	}
169	
170	fn is_http_token(byte: u8) -> bool {
171	    byte.is_ascii_alphanumeric()
172	        || matches!(
173	            byte,
174	            b'!' | b'#'
175	                | b'$'
176	                | b'%'
177	                | b'&'
178	                | b'\''
179	                | b'*'
180	                | b'+'
181	                | b'-'
182	                | b'.'
183	                | b'^'
184	                | b'_'
185	                | b'`'
186	                | b'|'
187	                | b'~'
188	        )
189	}
