  1	//! Parsing and validation for mapping-set TOML documents.
  2	
  3	use serde::Deserialize;
  4	
  5	use crate::{ACTION_CLASSES, SetError, normalize};
  6	
  7	#[derive(Debug, Deserialize)]
  8	#[serde(deny_unknown_fields)]
  9	pub(crate) struct MappingSet {
 10	    pub(crate) format_version: u32,
 11	    pub(crate) name: String,
 12	    pub(crate) description: Option<String>,
 13	    pub(crate) host: String,
 14	    pub(crate) rules: Vec<Rule>,
 15	}
 16	
 17	#[derive(Debug, Deserialize)]
 18	#[serde(deny_unknown_fields)]
 19	pub(crate) struct Rule {
 20	    pub(crate) method: Option<String>,
 21	    pub(crate) subdomain: Option<String>,
 22	    pub(crate) path: Option<String>,
 23	    pub(crate) action_class: String,
 24	}
 25	
 26	/// Converts one TOML document to a checked mapping set. Errors carry the
 27	/// set's declared name when the document parsed far enough to have one.
 28	pub(crate) fn parse(input: &str) -> Result<MappingSet, (Option<String>, SetError)> {
 29	    let set: MappingSet = toml::from_str(input).map_err(|error| (None, SetError::Toml(error)))?;
 30	    match validate(&set) {
 31	        Ok(()) => Ok(set),
 32	        Err(error) => Err((Some(set.name), error)),
 33	    }
 34	}
 35	
 36	fn validate(set: &MappingSet) -> Result<(), SetError> {
 37	    if set.format_version != 1 {
 38	        return Err(SetError::UnsupportedFormatVersion(set.format_version));
 39	    }
 40	    required_text("name", &set.name)?;
 41	    if set
 42	        .description
 43	        .as_deref()
 44	        .is_some_and(|description| description.chars().any(char::is_control))
 45	    {
 46	        return Err(SetError::InvalidField("description"));
 47	    }
 48	    validate_host(&set.host)?;
 49	    if set.rules.is_empty() {
 50	        return Err(SetError::InvalidField("rules"));
 51	    }
 52	
 53	    for (index, rule) in set.rules.iter().enumerate() {
 54	        if !ACTION_CLASSES.contains(&rule.action_class.as_str()) {
 55	            return Err(SetError::UnknownActionClass {
 56	                rule: index,
 57	                action_class: rule.action_class.clone(),
 58	            });
 59	        }
 60	        if let Some(method) = &rule.method
 61	            && normalize::method(method).is_none()
 62	        {
 63	            return Err(SetError::InvalidRule {
 64	                rule: index,
 65	                field: "method",
 66	            });
 67	        }
 68	        if let Some(subdomain) = &rule.subdomain
 69	            && subdomain != "*"
 70	            && (!is_dns_name(subdomain) || normalize::host(subdomain).is_none())
 71	        {
 72	            return Err(SetError::InvalidRule {
 73	                rule: index,
 74	                field: "subdomain",
 75	            });
 76	        }
 77	        if let Some(path) = &rule.path
 78	            && normalize::pattern_path(path).is_none()
 79	        {
 80	            return Err(SetError::InvalidRule {
 81	                rule: index,
 82	                field: "path",
 83	            });
 84	        }
 85	    }
 86	    Ok(())
 87	}
 88	
 89	fn required_text(field: &'static str, value: &str) -> Result<(), SetError> {
 90	    if value.trim().is_empty() || value.chars().any(char::is_control) {
 91	        Err(SetError::InvalidField(field))
 92	    } else {
 93	        Ok(())
 94	    }
 95	}
 96	
 97	fn validate_host(host: &str) -> Result<(), SetError> {
 98	    // Mapping hosts name an origin, not an HTTP authority. Ports and trailing
 99	    // dots are accepted for request authorities but create duplicate mapping
100	    // identities, so reject them here.
101	    if !host.contains(':')
102	        && !host.ends_with('.')
103	        && normalize::host(host).is_some()
104	        && is_dns_name(host)
105	    {
106	        Ok(())
107	    } else {
108	        Err(SetError::InvalidField("host"))
109	    }
110	}
111	
112	fn is_dns_name(value: &str) -> bool {
113	    !value.is_empty() && value.len() <= 253 && value.split('.').all(is_dns_label)
114	}
115	
116	fn is_dns_label(value: &str) -> bool {
117	    !value.is_empty()
118	        && value.len() <= 63
119	        && !value.starts_with('-')
120	        && !value.ends_with('-')
121	        && value
122	            .bytes()
123	            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
124	}
125	
126	#[cfg(test)]
127	mod tests {
128	    use super::parse;
129	
130	    const VALID: &str = r#"
131	format_version = 1
132	name = "Acme"
133	description = "Acme API"
134	host = "acme.com"
135	
136	[[rules]]
137	action_class = "payment.read"
138	"#;
139	
140	    #[test]
141	    fn parses_a_valid_mapping_set() {
142	        let set = parse(VALID).unwrap();
143	        assert_eq!(set.host, "acme.com");
144	        assert_eq!(set.rules.len(), 1);
145	    }
146	
147	    #[test]
148	    fn rejects_missing_required_top_level_fields() {
149	        for field in [
150	            "format_version = 1\n",
151	            "name = \"Acme\"\n",
152	            "host = \"acme.com\"\n",
153	        ] {
154	            let input = VALID.replace(field, "");
155	            assert!(parse(&input).is_err(), "expected {field:?} to be required");
156	        }
157	        assert!(
158	            parse(
159	                r#"
160	format_version = 1
161	name = "Acme"
162	description = "Acme API"
163	host = "acme.com"
164	"#
165	            )
166	            .is_err()
167	        );
168	        assert!(
169	            parse(
170	                r#"
171	format_version = 1
172	name = "Acme"
173	description = "Acme API"
174	host = "acme.com"
175	rules = []
176	"#
177	            )
178	            .is_err()
179	        );
180	    }
181	
182	    #[test]
183	    fn accepts_an_omitted_or_empty_description() {
184	        let omitted = VALID.replace("description = \"Acme API\"\n", "");
185	        assert_eq!(parse(&omitted).unwrap().description, None);
186	
187	        let empty = VALID.replace("description = \"Acme API\"", "description = \"\"");
188	        assert_eq!(parse(&empty).unwrap().description.as_deref(), Some(""));
189	    }
190	
191	    #[test]
192	    fn rejects_unknown_top_level_and_rule_keys() {
193	        for key in ["owner", "format_versoin", "descriptin", "hosts"] {
194	            assert!(
195	                parse(&format!("{VALID}\n{key} = \"value\"\n")).is_err(),
196	                "{key}"
197	            );
198	        }
199	        for key in ["action_clas", "actionclass", "methd", "subdomian", "paths"] {
200	            assert!(parse(&VALID.replace("action_class", key)).is_err(), "{key}");
201	        }
202	    }
203	
204	    #[test]
205	    fn rejects_unknown_action_classes_and_invalid_values() {
206	        assert!(parse(&VALID.replace("payment.read", "payments.delete")).is_err());
207	        assert!(
208	            parse(&VALID.replace("host = \"acme.com\"", "host = \"https://acme.com\"")).is_err()
209	        );
210	        assert!(
211	            parse(&VALID.replace(
212	                "action_class = \"payment.read\"",
213	                "path = \"relative\"\naction_class = \"payment.read\""
214	            ))
215	            .is_err()
216	        );
217	        assert!(parse(&VALID.replace("host = \"acme.com\"", "host = \"acme.com:443\"")).is_err());
218	        assert!(parse(&VALID.replace("host = \"acme.com\"", "host = \"192.0.2.1\"")).is_err());
219	    }
220	
221	    #[test]
222	    fn rejects_unsupported_versions_and_missing_rule_action_classes() {
223	        assert!(parse(&VALID.replace("format_version = 1", "format_version = 2")).is_err());
224	        assert!(
225	            parse(&VALID.replace("action_class = \"payment.read\"", "path = \"/v1\"")).is_err()
226	        );
227	    }
228	
229	    #[test]
230	    fn rejects_empty_and_malformed_matcher_values() {
231	        assert!(parse(&VALID.replace("name = \"Acme\"", "name = \"  \"")).is_err());
232	        assert!(
233	            parse(&VALID.replace(
234	                "action_class = \"payment.read\"",
235	                "method = \"GET /\"\naction_class = \"payment.read\""
236	            ))
237	            .is_err()
238	        );
239	        assert!(
240	            parse(&VALID.replace(
241	                "action_class = \"payment.read\"",
242	                "subdomain = \"api..internal\"\naction_class = \"payment.read\""
243	            ))
244	            .is_err()
245	        );
246	        assert!(
247	            parse(&VALID.replace(
248	                "action_class = \"payment.read\"",
249	                "subdomain = \"192.0.2.1\"\naction_class = \"payment.read\""
250	            ))
251	            .is_err()
252	        );
253	        assert!(
254	            parse(&VALID.replace(
255	                "action_class = \"payment.read\"",
256	                "path = \"/v1/%2fadmin\"\naction_class = \"payment.read\""
257	            ))
258	            .is_err()
259	        );
260	    }
261	
262	    #[test]
263	    fn rejects_malformed_hostnames_and_subdomains() {
264	        for host in [
265	            "-acme.com",
266	            "acme-.com",
267	            "acme..com",
268	            "acme_com",
269	            "acme.com.",
270	            "acme.com:443",
271	            "  acme.com",
272	        ] {
273	            let input = VALID.replace("host = \"acme.com\"", &format!("host = \"{host}\""));
274	            assert!(parse(&input).is_err(), "host {host:?}");
275	        }
276	
277	        for subdomain in ["-api", "api-", "api..internal", "api_internal", "api:443"] {
278	            let input = VALID.replace(
279	                "action_class = \"payment.read\"",
280	                &format!("subdomain = \"{subdomain}\"\naction_class = \"payment.read\""),
281	            );
282	            assert!(parse(&input).is_err(), "subdomain {subdomain:?}");
283	        }
284	    }
285	
286	    #[test]
287	    fn accepts_a_multi_label_exact_subdomain() {
288	        let input = VALID.replace(
289	            "action_class = \"payment.read\"",
290	            "subdomain = \"api.eu\"\naction_class = \"payment.read\"",
291	        );
292	        assert!(parse(&input).is_ok());
293	    }
294	
295	    #[test]
296	    fn accepts_optional_rule_matchers() {
297	        let input = VALID.replace("action_class = \"payment.read\"", "method = \"PATCH\"\nsubdomain = \"*\"\npath = \"/v1/*\"\naction_class = \"payment.read\"");
298	        assert!(parse(&input).is_ok());
299	    }
300	}
  1	//! Compiled-rule matching, lexicographic specificity, and load-time conflicts.
  2	
  3	use std::cmp::Ordering;
  4	
  5	use crate::normalize;
  6	
  7	#[derive(Debug, Clone, PartialEq, Eq)]
  8	pub(crate) enum HostPattern {
  9	    Bare(String),
 10	    Exact(String),
 11	    AnySubdomain(String),
 12	}
 13	
 14	#[derive(Debug, Clone)]
 15	pub(crate) struct CompiledRule {
 16	    pub(crate) method: Option<String>,
 17	    pub(crate) host: HostPattern,
 18	    pub(crate) path: Option<String>,
 19	    pub(crate) action_class: String,
 20	    specificity: Specificity,
 21	}
 22	
 23	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 24	struct Specificity {
 25	    host: u8,
 26	    path_kind: u8,
 27	    literal_count: usize,
 28	    inverted_wildcard_count: usize,
 29	    literal_prefix: usize,
 30	    method: u8,
 31	}
 32	
 33	impl Ord for Specificity {
 34	    fn cmp(&self, other: &Self) -> Ordering {
 35	        (
 36	            self.host,
 37	            self.path_kind,
 38	            self.literal_count,
 39	            self.inverted_wildcard_count,
 40	            self.literal_prefix,
 41	            self.method,
 42	        )
 43	            .cmp(&(
 44	                other.host,
 45	                other.path_kind,
 46	                other.literal_count,
 47	                other.inverted_wildcard_count,
 48	                other.literal_prefix,
 49	                other.method,
 50	            ))
 51	    }
 52	}
 53	
 54	impl PartialOrd for Specificity {
 55	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
 56	        Some(self.cmp(other))
 57	    }
 58	}
 59	
 60	#[derive(Debug)]
 61	pub(crate) enum CompileError {
 62	    Host,
 63	    Method,
 64	    Path,
 65	}
 66	
 67	#[derive(Debug)]
 68	pub(crate) enum ConflictCheckError {
 69	    TooComplex { first: usize, second: usize },
 70	}
 71	
 72	impl CompiledRule {
 73	    pub(crate) fn new(
 74	        method: Option<&str>,
 75	        base_host: &str,
 76	        subdomain: Option<&str>,
 77	        path: Option<&str>,
 78	        action_class: String,
 79	    ) -> Result<Self, CompileError> {
 80	        let base_host = normalize::host(base_host).ok_or(CompileError::Host)?;
 81	        let host = match subdomain {
 82	            None => HostPattern::Bare(base_host),
 83	            Some("*") => HostPattern::AnySubdomain(base_host),
 84	            Some(value) => {
 85	                let value = normalize::host(value).ok_or(CompileError::Host)?;
 86	                HostPattern::Exact(format!("{value}.{base_host}"))
 87	            }
 88	        };
 89	        let method = match method {
 90	            Some(value) => Some(normalize::method(value).ok_or(CompileError::Method)?),
 91	            None => None,
 92	        };
 93	        let path = match path {
 94	            Some(value) => Some(normalize::pattern_path(value).ok_or(CompileError::Path)?),
 95	            None => None,
 96	        };
 97	        let specificity = specificity(&host, method.is_some(), path.as_deref());
 98	        Ok(Self {
 99	            method,
100	            host,
101	            path,
102	            action_class,
103	            specificity,
104	        })
105	    }
106	
107	    pub(crate) fn matches(&self, method: &str, host: &str, path: &str) -> bool {
108	        self.method
109	            .as_deref()
110	            .is_none_or(|expected| expected == method)
111	            && host_matches(&self.host, host)
112	            && self
113	                .path
114	                .as_deref()
115	                .is_none_or(|pattern| glob_matches(pattern, path))
116	    }
117	
118	    pub(crate) fn compare_specificity(&self, other: &Self) -> Ordering {
119	        self.specificity.cmp(&other.specificity)
120	    }
121	}
122	
123	pub(crate) fn find_conflict(
124	    rules: &[CompiledRule],
125	) -> Result<Option<(usize, usize)>, ConflictCheckError> {
126	    let mut checked_pairs = 0;
127	    for (right_index, right) in rules.iter().enumerate() {
128	        for (left_index, left) in rules[..right_index].iter().enumerate() {
129	            checked_pairs += 1;
130	            if checked_pairs > MAX_CONFLICT_PAIR_CHECKS {
131	                return Err(ConflictCheckError::TooComplex {
132	                    first: left_index,
133	                    second: right_index,
134	                });
135	            }
136	            if left.action_class != right.action_class
137	                && left.specificity == right.specificity
138	                && methods_overlap(left.method.as_deref(), right.method.as_deref())
139	                && hosts_overlap(&left.host, &right.host)
140	            {
141	                match paths_overlap(left.path.as_deref(), right.path.as_deref()) {
142	                    Ok(true) => return Ok(Some((left_index, right_index))),
143	                    Ok(false) => {}
144	                    Err(()) => {
145	                        return Err(ConflictCheckError::TooComplex {
146	                            first: left_index,
147	                            second: right_index,
148	                        });
149	                    }
150	                }
151	            }
152	        }
153	    }
154	    Ok(None)
155	}
156	
157	fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
158	    let host = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
159	    let (path_kind, literal_count, wildcard_count, literal_prefix) = match path {
160	        None => (0, 0, 0, 0),
161	        Some(value) if !value.contains('*') => (2, value.len(), 0, value.len()),
162	        Some(value) => (
163	            1,
164	            value.bytes().filter(|byte| *byte != b'*').count(),
165	            value.bytes().filter(|byte| *byte == b'*').count(),
166	            value.find('*').unwrap_or(0),
167	        ),
168	    };
169	    Specificity {
170	        host,
171	        path_kind,
172	        literal_count,
173	        inverted_wildcard_count: usize::MAX - wildcard_count,
174	        literal_prefix,
175	        method: u8::from(has_method),
176	    }
177	}
178	
179	fn host_matches(pattern: &HostPattern, host: &str) -> bool {
180	    match pattern {
181	        HostPattern::Bare(expected) | HostPattern::Exact(expected) => expected == host,
182	        HostPattern::AnySubdomain(base) => host
183	            .strip_suffix(base)
184	            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1),
185	    }
186	}
187	
188	fn methods_overlap(left: Option<&str>, right: Option<&str>) -> bool {
189	    left.is_none() || right.is_none() || left == right
190	}
191	
192	fn hosts_overlap(left: &HostPattern, right: &HostPattern) -> bool {
193	    match (left, right) {
194	        (HostPattern::Bare(a), HostPattern::Bare(b))
195	        | (HostPattern::Bare(a), HostPattern::Exact(b))
196	        | (HostPattern::Exact(a), HostPattern::Bare(b))
197	        | (HostPattern::Exact(a), HostPattern::Exact(b)) => a == b,
198	        // These pairs cannot have equal host specificity, but retain correct
199	        // overlap semantics for callers that want them.
200	        (HostPattern::AnySubdomain(base), HostPattern::Bare(host))
201	        | (HostPattern::Bare(host), HostPattern::AnySubdomain(base))
202	        | (HostPattern::AnySubdomain(base), HostPattern::Exact(host))
203	        | (HostPattern::Exact(host), HostPattern::AnySubdomain(base)) => {
204	            host_matches(&HostPattern::AnySubdomain(base.clone()), host)
205	        }
206	        (HostPattern::AnySubdomain(a), HostPattern::AnySubdomain(b)) => {
207	            a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"))
208	        }
209	    }
210	}
211	
212	fn paths_overlap(left: Option<&str>, right: Option<&str>) -> Result<bool, ()> {
213	    match (left, right) {
214	        (None, _) | (_, None) => Ok(true),
215	        (Some(left), Some(right)) => globs_overlap(left, right),
216	    }
217	}
218	
219	pub(crate) fn glob_matches(pattern: &str, value: &str) -> bool {
220	    let pattern = pattern.as_bytes();
221	    let value = value.as_bytes();
222	    let (mut p, mut v, mut star, mut retry) = (0, 0, None, 0);
223	    while v < value.len() {
224	        while p < pattern.len() && pattern[p] == b'*' {
225	            star = Some(p);
226	            p += 1;
227	            retry = v;
228	        }
229	        if p < pattern.len() && pattern[p] == value[v] {
230	            p += 1;
231	            v += 1;
232	        } else if let Some(star_index) = star {
233	            p = star_index + 1;
234	            retry += 1;
235	            v = retry;
236	        } else {
237	            return false;
238	        }
239	    }
240	    while p < pattern.len() && pattern[p] == b'*' {
241	        p += 1;
242	    }
243	    p == pattern.len()
244	}
245	
246	/// Product traversal of two `*` glob NFAs. The sentinel represents any byte
247	/// not currently present as a literal and keeps the alphabet finite.
248	const MAX_GLOB_OVERLAP_STATES: usize = 1_000_000;
249	const MAX_CONFLICT_PAIR_CHECKS: usize = 100_000;
250	
251	fn globs_overlap(left: &str, right: &str) -> Result<bool, ()> {
252	    let (left, right) = (left.as_bytes(), right.as_bytes());
253	    let width = right.len().checked_add(1).ok_or(())?;
254	    let states = left
255	        .len()
256	        .checked_add(1)
257	        .and_then(|height| height.checked_mul(width))
258	        .filter(|states| *states <= MAX_GLOB_OVERLAP_STATES)
259	        .ok_or(())?;
260	    let mut seen = vec![false; states];
261	    let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
262	    while let Some((i, j)) = queue.pop_front() {
263	        let state = i * width + j;
264	        if seen[state] {
265	            continue;
266	        }
267	        seen[state] = true;
268	        if i == left.len() && j == right.len() {
269	            return Ok(true);
270	        }
271	        if left.get(i) == Some(&b'*') {
272	            queue.push_back((i + 1, j));
273	        }
274	        if right.get(j) == Some(&b'*') {
275	            queue.push_back((i, j + 1));
276	        }
277	        let mut alphabet = vec![0];
278	        if let Some(&byte) = left.get(i).filter(|&&byte| byte != b'*') {
279	            alphabet.push(byte);
280	        }
281	        if let Some(&byte) = right.get(j).filter(|&&byte| byte != b'*') {
282	            alphabet.push(byte);
283	        }
284	        for byte in alphabet {
285	            let next_left = transition(left, i, byte);
286	            let next_right = transition(right, j, byte);
287	            if let (Some(next_left), Some(next_right)) = (next_left, next_right) {
288	                queue.push_back((next_left, next_right));
289	            }
290	        }
291	    }
292	    Ok(false)
293	}
294	
295	fn transition(pattern: &[u8], index: usize, byte: u8) -> Option<usize> {
296	    match pattern.get(index) {
297	        Some(b'*') => Some(index),
298	        Some(&literal) if literal == byte => Some(index + 1),
299	        _ => None,
300	    }
301	}
