  2	
  3	use std::sync::Arc;
  4	
  5	use action_classifier::{Classifier, load};
  6	
  7	const ACME: &str = r#"
  8	format_version = 1
  9	name = "Acme"
 10	description = "Acme API"
 11	host = "acme.com"
 12	
 13	[[rules]]
 14	subdomain = "*"
 15	action_class = "repo.read"
 16	
 17	[[rules]]
 18	subdomain = "api"
 19	path = "/v1/*"
 20	action_class = "payment.read"
 21	
 22	[[rules]]
 23	subdomain = "api"
 24	method = "POST"
 25	path = "/v1/*"
 26	action_class = "payment.create"
 27	
 28	[[rules]]
 29	subdomain = "api"
 30	path = "/v1/refunds/*"
 31	action_class = "payment.refund"
 32	
 33	[[rules]]
 34	subdomain = "api"
 35	path = "/v1/*/send"
 36	action_class = "communication.external.send"
