 38	[[rules]]
 39	path = "/pricing"
 40	action_class = "payment.read"
 41	"#;
 42	
 43	#[tokio::test]
 44	async fn host_patterns_respect_label_boundaries() {
 45	    let c = load(&[ACME]).await.unwrap();
 46	    let cases = [
 47	        ("API.Acme.COM", Some("payment.read")),
 48	        ("api.acme.com.", Some("payment.read")),
 49	        ("api.acme.com:8443", Some("payment.read")),
 50	        ("a.b.acme.com", Some("repo.read")),
 51	        ("evilacme.com", None),
 52	        ("api.acme.com.evil.com", None),
 53	        ("acme.com.evil.com", None),
 54	        ("user@api.acme.com", None),
 55	        ("192.0.2.1", None),
 56	    ];
 57	    for (host, expected) in cases {
 58	        assert_eq!(c.classify("GET", host, "/v1/x").await, expected, "{host}");
 59	    }
 60	    // `*` does not cover the bare host, and the bare-host rule only covers it.
 61	    assert_eq!(c.classify("GET", "acme.com", "/v1/x").await, None);
 62	    assert_eq!(
 63	        c.classify("GET", "acme.com", "/pricing").await,
 64	        Some("payment.read")
 65	    );
 66	    assert_eq!(
 67	        c.classify("GET", "www.acme.com", "/pricing").await,
 68	        Some("repo.read")
 69	    );
 70	}
 71	
 72	#[tokio::test]
 73	async fn most_specific_rule_wins() {
 74	    let c = load(&[ACME]).await.unwrap();
 75	    let cases = [
 76	        // Exact subdomain beats wildcard subdomain even with a broader path.
 77	        ("GET", "/v1/x", Some("payment.read")),
 78	        // Explicit method beats omitted method once host and path tie.
 79	        ("POST", "/v1/x", Some("payment.create")),
 80	        // More literal characters beat a method on a broader pattern.
 81	        ("POST", "/v1/refunds/r1", Some("payment.refund")),
 82	        // The slash-appended form falls back to `/v1/*`, so both spellings
 83	        // are conservatively unclassified.
 84	        ("GET", "/v1/msg/send", None),
 85	        // A path no exact-host rule covers falls back to the wildcard host.
 86	        ("GET", "/v2/x", Some("repo.read")),
 87	    ];
 88	    for (method, path, expected) in cases {
 89	        assert_eq!(
 90	            c.classify(method, "api.acme.com", path).await,
 91	            expected,
 92	            "{method} {path}"
 93	        );
 94	    }
 95	}
