 97	#[tokio::test]
 98	async fn malformed_requests_never_panic_or_classify() {
 99	    let c = load(&[ACME]).await.unwrap();
100	    let long = "a".repeat(64 * 1024);
101	    let inputs: [(&str, &str, &str); 8] = [
102	        ("", "api.acme.com", "/v1/x"),
103	        ("GE T", "api.acme.com", "/v1/x"),
104	        ("GET", "", "/v1/x"),
105	        ("GET", "api.acme.com:", "/v1/x"),
106	        ("GET", "api.acme.com:99999", "/v1/x"),
107	        ("GET", "аpi.acme.com", "/v1/x"),
108	        ("GET", "api.acme.com", "/v1/\u{1F600}"),
109	        ("GET", "api.acme.com", "v1/x"),
110	    ];
111	    for (method, host, path) in inputs {
112	        assert_eq!(
113	            c.classify(method, host, path).await,
114	            None,
115	            "{method:?} {host:?} {path:?}"
116	        );
117	    }
118	    for value in [long.as_str(), "%", "%%%", "\0", "\u{10FFFF}"] {
119	        let _ = c.classify(value, value, value).await;
120	        let _ = c.classify("GET", "api.acme.com", value).await;
121	    }
122	}
