130	#[test]
131	fn concurrent_classification_is_consistent() {
132	    let runtime = tokio::runtime::Builder::new_current_thread()
133	        .build()
134	        .unwrap();
135	    let classifier = Arc::new(runtime.block_on(load(&[ACME])).unwrap());
136	    std::thread::scope(|scope| {
137	        for _ in 0..8 {
138	            let classifier = Arc::clone(&classifier);
139	            scope.spawn(move || {
140	                let runtime = tokio::runtime::Builder::new_current_thread()
141	                    .build()
142	                    .unwrap();
143	                for _ in 0..1_000 {
144	                    let (create, refund) = runtime.block_on(async {
145	                        (
146	                            classifier.classify("POST", "api.acme.com", "/v1/x").await,
147	                            classifier
148	                                .classify("POST", "api.acme.com", "/v1/refunds/r")
149	                                .await,
150	                        )
151	                    });
152	                    assert_eq!(create, Some("payment.create"));
153	                    assert_eq!(refund, Some("payment.refund"));
154	                }
155	            });
156	        }
157	    });
158	}
  1	//! Load-time conflict detection and set-order independence.
