  1	//! Deterministic generated-input checks for the public API.
  2	
  3	use action_classifier::load;
  4	
  5	const PAYMENTS: &str = r#"
  6	format_version = 1
  7	name = "Payments"
  8	host = "acme.com"
  9	
 10	[[rules]]
 11	subdomain = "api"
 12	path = "/v1/*"
 13	action_class = "payment.read"
 14	
 15	[[rules]]
 16	subdomain = "api"
 17	method = "POST"
 18	path = "/v1/refunds/*"
 19	action_class = "payment.refund"
 20	"#;
 21	
 22	const REPOS: &str = r#"
 23	format_version = 1
 24	name = "Repos"
 25	host = "acme.com"
 26	
 27	[[rules]]
 28	subdomain = "*"
 29	action_class = "repo.read"
 30	"#;
 31	
 32	/// A small, repeatable generator keeps this robustness coverage dependency-free.
 33	fn generated_text(state: &mut u64, maximum_length: usize) -> String {
 34	    const ALPHABET: &[char] = &[
 35	        'a', 'Z', '0', '/', '.', '*', '%', ':', '@', ' ', '\\', '\0', '\n', 'é', '🦀',
 36	    ];
 37	    let length = usize::try_from(next(state)).unwrap_or(0) % (maximum_length + 1);
 38	    (0..length)
 39	        .map(|_| ALPHABET[usize::try_from(next(state)).unwrap_or(0) % ALPHABET.len()])
 40	        .collect()
 41	}
 42	
 43	fn next(state: &mut u64) -> u64 {
 44	    *state ^= *state << 13;
 45	    *state ^= *state >> 7;
 46	    *state ^= *state << 17;
 47	    *state
 48	}
 49	
 50	#[tokio::test]
 51	async fn generated_inputs_never_panic_and_are_deterministic() {
 52	    let classifier = load(&[PAYMENTS, REPOS]).await.unwrap();
 53	    let mut state = 0x5EED_CAFE_BAAD_F00D;
 54	
 55	    for _ in 0..2_000 {
 56	        let method = generated_text(&mut state, 32);
 57	        let host = generated_text(&mut state, 128);
 58	        let path = generated_text(&mut state, 256);
 59	        let first = classifier.classify(&method, &host, &path).await;
 60	        let second = classifier.classify(&method, &host, &path).await;
 61	        assert_eq!(first, second, "{method:?} {host:?} {path:?}");
 62	    }
 63	}
 64	
 65	#[tokio::test]
 66	async fn generated_inputs_are_independent_of_mapping_set_order() {
 67	    let forward = load(&[PAYMENTS, REPOS]).await.unwrap();
 68	    let reverse = load(&[REPOS, PAYMENTS]).await.unwrap();
 69	    let mut state = 0x1234_5678_9ABC_DEF0;
 70	
 71	    for _ in 0..2_000 {
 72	        let method = generated_text(&mut state, 32);
 73	        let host = generated_text(&mut state, 128);
 74	        let path = generated_text(&mut state, 256);
 75	        assert_eq!(
 76	            forward.classify(&method, &host, &path).await,
 77	            reverse.classify(&method, &host, &path).await,
 78	            "{method:?} {host:?} {path:?}"
 79	        );
 80	    }
 81	}
