  5	fn set(name: &str, host: &str, rules: &str) -> String {
  6	    format!("format_version = 1\nname = {name:?}\ndescription = \"test\"\nhost = {host:?}\n{rules}")
  7	}
  8	
  9	fn rule(subdomain: Option<&str>, method: Option<&str>, path: Option<&str>, class: &str) -> String {
 10	    let mut out = String::from("\n[[rules]]\n");
 11	    for (key, value) in [("subdomain", subdomain), ("method", method), ("path", path)] {
 12	        if let Some(value) = value {
 13	            out.push_str(&format!("{key} = {value:?}\n"));
 14	        }
 15	    }
 16	    out.push_str(&format!("action_class = {class:?}\n"));
 17	    out
 18	}
