    let rev = load(&[&render(&[5,4,3,2,1,0])]).await.unwrap();
    let mut diffs = 0; let mut somes = 0; let mut total = 0;
    for m in ["GET","POST","DELETE","get"] { for h in ["api.acme.com","x.acme.com","acme.com","a.b.acme.com"] {
        for p in ["/","/v1","/v1/","/v1/x","/v1/refunds","/v1/refunds/","/v1/refunds/x","/v1/msg/send","/v1/msg/send/","/v2/x","/v1/refunds/send"] {
