            if a.is_some() { somes += 1; assert!(ACTION_CLASSES.contains(&a.unwrap())); }
            if a != b { diffs += 1; println!("DIFF {m} {h}{p}: {a:?} vs {b:?}"); }
        }}}
    println!("{total} requests, {somes} classified, {diffs} order-dependent");
    for p in ["/v1/msg/send","/v1/refunds","/v1/refunds/"] {
        println!("GET api.acme.com{p} -> {:?}", fwd.classify("GET","api.acme.com",p).await);
    }
