action_class = "communication.external.send"
[[rules]]
subdomain = "api"
method = "GET"
path = "/2010-04-01/Accounts/*/Messages.json"
action_class = "communication.external.send"
"#);
    let c = load(&[&twilio]).await.unwrap();
    for (m,p) in [("GET","/2010-04-01/Accounts/AC1/Messages.json"),("GET","/2010-04-01/Accounts/AC1/Calls.json")] {
        println!("{m} {p} -> {:?}", c.classify(m,"api.twilio.com",p).await);
    }
    let gh = set("GH","github.com", r#"
[[rules]]
subdomain = "api"
path = "/repos/*"
action_class = "repo.read"
[[rules]]
subdomain = "api"
method = "PUT"
path = "/repos/*/contents/*"
action_class = "repo.write"
[[rules]]
subdomain = "api"
method = "PUT"
path = "/repos/*"
action_class = "repo.read"
"#);
    let c = load(&[&gh]).await.unwrap();
    println!("PUT /repos/Org/Repo/contents/README.md -> {:?}", c.classify("PUT","api.github.com","/repos/Org/Repo/contents/README.md").await);
    let mixed = set("M","acme.com", r#"
[[rules]]
subdomain = "api"
path = "/v1/*"
action_class = "payment.read"
[[rules]]
subdomain = "api"
path = "/v1/Refunds/*"
action_class = "payment.refund"
"#);
    let c = load(&[&mixed]).await.unwrap();
    for p in ["/v1/Refunds/r1","/v1/refunds/r1","/v1/REFUNDS/r1"] {
        println!("rule '/v1/Refunds/*': POST {p} -> {:?}", c.classify("POST","api.acme.com",p).await);
    }

    println!("\n== H9: cap counts the query string ==");
    let acme = set("A","acme.com","\n[[rules]]\nsubdomain=\"api\"\npath=\"/v1/*\"\naction_class=\"payment.read\"\n");
    let c = load(&[&acme]).await.unwrap();
    let q = format!("/v1/search?q={}", "x".repeat(8_200));
    println!("GET /v1/search?q=<8.2KB> -> {:?}", c.classify("GET","api.acme.com",&q).await);

    println!("\n== Audit 11 MED still at HEAD? exact-path two-class rules ==");
    for n in [200usize, 400, 2000] {
        let rules: String = (0..n).map(|i| format!("\n[[rules]]\npath=\"/api/{i:05}\"\naction_class={:?}\n", if i%2==0 {"repo.read"} else {"repo.write"})).collect();
        let s = set("R","acme.com",&rules);
        let t = Instant::now(); let r = load(&[&s]).await;
        println!("n={n}: {:?} {:?}", r.err().map(|e| e.to_string()), t.elapsed());
    }

    println!("\n== classify cost, 200 rules, 8KB path ==");
    let rules: String = (0..200).map(|i| format!("\n[[rules]]\nsubdomain=\"api\"\npath=\"/r{i}/*\"\naction_class=\"repo.read\"\n")).collect();
    let c = load(&[&set("P","acme.com",&rules)]).await.unwrap();
    let p = format!("/r1/{}/", "A".repeat(8_180));
    let t = Instant::now(); for _ in 0..1000 { let _ = c.classify("GET","api.acme.com",&p).await; }
    println!("avg {:?}", t.elapsed()/1000);
}
EOF
